 {id:9,name:"Murugan K",role:"Security",dept:"Main Gate",joined:"2021-03-01",phone:"98400 44009",basic:13000,hra:3250,allow:1500,pf:1560,tax:0,bank:"SBI ····3390",status:"On Leave"}
